from typing import NamedTuple
import numpy as np

# Define the core primitives used in the JAX core (autodifferentiation and transformation) framework
class Primitive(NamedTuple):
  name: str

# Primitives for basic operations
add_p = Primitive('add')
mul_p = Primitive('mul')
neg_p = Primitive('neg')
sin_p = Primitive('sin')
cos_p = Primitive('cos')
reduce_sum_p = Primitive('reduce_sum')
greater_p = Primitive('greater')
less_p = Primitive('less')
transpose_p = Primitive('transpose')
broadcast_p = Primitive('broadcast')

# These helper functions wrap the primitive binding and dispatch mechanism.
# They use a helper called bind1 (not shown in full here) that invokes the current trace's
# interpretation rules. The idea is that every primitive application is intercepted.

def add(x, y):
  return bind1(add_p, x, y)

def mul(x, y):
  return bind1(mul_p, x, y)

def neg(x):
  return bind1(neg_p, x)

def sin(x):
  return bind1(sin_p, x)

def cos(x):
  return bind1(cos_p, x)

def greater(x, y):
  return bind1(greater_p, x, y)

def less(x, y):
  return bind1(less_p, x, y)

def transpose(x, perm):
  return bind1(transpose_p, x, perm=perm)

def broadcast(x, shape, axes):
  return bind1(broadcast_p, x, shape=shape, axes=axes)

def reduce_sum(x, axis=None):
  if axis is None:
    axis = tuple(range(np.ndim(x)))
  if isinstance(axis, int):
    axis = (axis,)
  return bind1(reduce_sum_p, x, axis=axis)

# The binding function that looks up the current interpreter (trace) on the interpreter stack
# and dispatches the primitive application accordingly.

def bind(prim, *args, **params):
  top_trace = find_top_trace(args)
  tracers = [full_raise(top_trace, arg) for arg in args]
  outs = top_trace.process_primitive(prim, tracers, params)
  return [full_lower(out) for out in outs]

# For context‐sensitive interpretation, we maintain a global stack of active traces
trace_stack = []

def new_main(trace_type, global_data=None):
  level = len(trace_stack)
  main = MainTrace(level, trace_type, global_data)
  trace_stack.append(main)
  return main

class MainTrace(NamedTuple):
  level: int
  trace_type: type
  global_data: any

# Example implementations for full_raise and full_lower which box/unbox values into tracers

def full_raise(trace, val):
  # If value is not already a tracer, box it using the trace's 'pure' method
  if not isinstance(val, Tracer):
    return trace.pure(val)
  if val._trace.main == trace.main:
    return val
  elif val._trace.main.level < trace.main.level:
    return trace.lift(val)
  else:
    raise Exception('Cannot raise tracer from a higher level')


def full_lower(val):
  if isinstance(val, Tracer):
    return val.full_lower()
  else:
    return val

# Base Tracer class which forwards common operations to the wrapped abstract value
class Tracer:
  _trace: any

  @property
  def aval(self):
    raise NotImplementedError

  def full_lower(self):
    return self

  def __neg__(self): return self.aval._neg(self)
  def __add__(self, other): return self.aval._add(self, other)
  def __radd__(self, other): return self.aval._radd(self, other)
  def __mul__(self, other): return self.aval._mul(self, other)
  def __rmul__(self, other): return self.aval._rmul(self, other)

# The functions above form the core mechanism that underlies JAX's method: by intercepting
# each primitive call via bind() and dispatching according to the current trace, one can
# implement forward-mode AD (via JVPTracer/JVPTrace), reverse-mode AD (via transposition
# of jaxprs), JIT compilation (by staging a computation to a jaxpr and lowering it to XLA),
# and so on. This context-guided dispatch enables flexible transformation of user-defined
# functions in a composable way.

# (Note: bind1, find_top_trace, and the specialized Trace subclasses are defined elsewhere
# in the repository, forming a multi-stage tracing and transformation system.)
